function toDateInput(s) {
  if (!s) return "";
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (!m) return "";
  const [, mo, d, y] = m;
  const year = y.length === 2 ? parseInt(y) < 50 ? "20" + y : "19" + y : y;
  return `${year}-${mo.padStart(2, "0")}-${d.padStart(2, "0")}`;
}
